local _, WFJ = ...
WFJ.Data.add("quest", {
  [80001] = { "Riaccendere il fuoco", nil, nil, nil, nil, 0xef1f92bd, nil, nil, nil, nil, ".mmmm" },
  [80241] = { "Le origini della forgiatura", "Porta 6 ⟦Golden Scale Bracers=Bracciali di Scaglie d'Oro⟧ a ⟦Hank the Hammer=Hank il Martello⟧, a ⟦Stormwind=Roccavento⟧.", "Quando avevo più o meno la tua età, un nano di nome Galvan mi prese sotto la sua ala e mi insegnò l'arte del fabbro d'armature. Prima di partire per la ⟦Booty Bay=Baia del Bottino⟧, mi fece promettere di addestrare tutti coloro che avessero il desiderio e la determinazione di progredire nell'arte della forgiatura; ed eccomi qui, dopo tutti questi anni.\n\nE ora è il momento che tu impari qualcosa. Fabbricami sei bracciali di scaglie d'oro e scoprirai da dove nasce la forgiatura, {name}.", nil, nil, 0x5dd39489, 0x350387d3, 0x870eb53b, nil, nil, "...mm" },
  [80324] = { "Il re folle", "Porta gli Appunti di Ingegneria di Thermaplugg al ⟦High Tinker Mekkatorque=Gran Meccanista Meccatork⟧ a Tinker Town, a ⟦Ironforge=Forgiardente⟧.", "Trovi un taccuino sporco e logoro, pieno di schemi e appunti scarabocchiati. Anche a una rapida occhiata è chiarissimo che ognuna di queste creazioni potrebbe essere usata per scatenare un caos terribile, se mai qualcuno fosse tanto sciocco da costruirle.", nil, nil, 0x9a355483, 0x6e44d587, 0x04cc27a6, nil, nil, "...mm" },
  [80325] = { "Il re folle", "Porta gli Appunti di Ingegneria di Thermaplugg a Nogg nella ⟦Valley of Honor=Valle dell'Onore⟧ a Orgrimmar.", "Trovi un taccuino sporco e logoro, pieno di schemi e appunti scarabocchiati. Anche a una rapida occhiata è chiarissimo che ognuna di queste creazioni potrebbe essere usata per scatenare un caos terribile, se mai qualcuno fosse tanto sciocco da costruirle.", nil, nil, 0x9a355483, 0x1a8222d8, 0x04cc27a6, nil, nil, "...mm" },
  [80411] = { "Il Talismano di Kazdor", "Trova il Talismano di Kazdor all'interno di ⟦Zul'Farrak=Zul'farrak⟧. Poi portalo a Fahrad al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧. Devi portare a termine l'incarico da <solo/sola>.", "Dall'ultima lettera che abbiamo intercettato, sembra che l'ultimo artefatto che Caius desidera sia il Talismano di Kazdor. La lettera dice che questo talismano si trova da qualche parte dentro ⟦Zul'Farrak=Zul'farrak⟧.\n\nVoglio che porti a termine il lavoro secondo le istruzioni di Caius, per non destare i suoi sospetti. Questo significa che dovrai entrare a ⟦Zul'Farrak=Zul'farrak⟧ da sol<o/a>, come al solito.\n\nPrima di consegnare il Talismano, però, riportalo qui. Daremo a Caius qualcosa in più di quanto ha chiesto.", nil, nil, 0x2dd4f6ca, 0x3fc75edd, 0xf3018f25, nil, nil, "...mm" },
  [80453] = { "Piani ben congegnati", "Porta il Talismano di Kazdor a Zan Stranavite nel seminterrato del ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Porta il talismano giù da Zan Stranavite, nel seminterrato. Gli ho chiesto di dotare l'artefatto di un meccanismo che rilevi qualsiasi tentativo di incanalare energia magica dentro o fuori di esso.\n\nIl meccanismo è praticamente invisibile a occhio nudo e detonerà quando attivato. Con un po' di fortuna, Caius morirà nell'esplosione. Come minimo, i suoi piani per il talismano saranno vanificati.", nil, nil, 0xccdf2846, 0x02436916, 0xe09b8edb, nil, nil, "...mm" },
  [80454] = { "Un'ultima goccia", "Porta il Talismano Modificato al punto di scambio segreto di Caius vicino a ⟦Pyrewood Village=Rovonero⟧.", "L'esca è pronta, ora dobbiamo tendere la trappola. Ho modificato il talismano secondo le istruzioni di Fahrad. Non resta che consegnarlo, come hai fatto con gli altri artefatti.\n\nVa' alla baita vicino a ⟦Pyrewood Village=Rovonero⟧ e metti questo talismano modificato nel punto di scambio segreto di Caius.\n\nQuel che segue, per ora, non dipende da noi.", nil, nil, 0x440f7068, 0xdb6c6be6, 0x0fa6f7f5, nil, nil, "...mm" },
  [80455] = { "Aspettando il momento giusto", "Torna da Fahrad al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Il lavoro è fatto. Meglio tornare a ⟦Ravenholdt=Corvolesto⟧ e avvisare Fahrad.", nil, nil, 0x1b8d3e4a, 0xa5e27d78, 0x65418637, nil, nil, "...mm" },
  [80526] = { "Ingannami due volte", "Parla con Fahrad quando sei <pronto/pronta> a sentire il suo piano.", "Non un momento troppo presto, {name}\n\nIl maniero tiene d'occhio questo personaggio 'C' con cui hai avuto a che fare.\n\nLa vera identità di C è Caius Selvanera, un potente utilizzatore di magia che lavora con la ⟦Syndicate=Lega dei Tagliagole⟧. Le nostre fonti dicono che raccoglie artefatti per uno scopo ignoto. Solo di recente abbiamo scoperto che eri *tu* a procurarglieli.\n\nCaius deve essere fermato, e credo che spetti a te farlo. Per fortuna ho escogitato un piano. Vieni a parlarmi quando sei pront<o/a> a ripulire il tuo nome.", nil, nil, 0x5cd2700b, 0x8adb321e, 0x68911841, nil, nil, "...mm" },
})
